  'The hayd has ended — what follows is istihada': 'حیض پای ته رسېدلی — څه چې ورپسې راځي استحاضه ده',
  'The official channels from Makkah and Madinah': 'د مکې او مدینې رسمي چینلونه',
  'The pillar of Hajj, and Sa‘i if it is still owed': 'د حج رکن، او سعي که لا پاتې وي',
  'The post-natal bleeding has ended — what follows is istihada': 'د زیږون وروسته وینه پای ته رسېدلې — څه چې ورپسې راځي استحاضه ده',
  'The printed Mushaf hand, with full Quranic marks': 'د چاپ شوي مصحف خط، د قرآني پوره نښو سره',
